/************************************************************* 
* 함수명   : ShowWin(sval)
* 설명       : 화면 로딩중 표시를 Display 한다.
		   sval : grid ID
*************************************************************/
/**
 * @method
 * @name ShowWin
 * @description desc
 * @param {string} sval desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.ShowWin = async function(sval) {
    //세션타임 제한을 위해 시간초기화 yako_201912
    $c.frame.path("/top").initTime();
    if ($c.frame.path("NoData") != null) {
        await $c.frame.CloseFrame();
    }
    var tem1 = sval.style.getStyle("width");
    var temLeft = sval.style.left;
    var temTop = sval.style.top;
    var tem2 = sval.style.getStyle("height");
    tem1 = tem1.substring(0, (tem1.length - 2));
    temLeft = temLeft.substring(0, (temLeft.length - 2));
    tem2 = tem2.substring(0, (tem2.length - 2));
    temTop = temTop.substring(0, (temTop.length - 2));
    vXpos = (eval(tem1 / 2) - 65) + Number(temLeft);
    vYpos = (eval(tem2 / 2) - 18) + Number(temTop);
    if ($c.frame.path("LoadingImg") == null) {
        await $c.frame.CreateFrame("LoadingImg", "/common/LoadingImg.gfm", "페이지 로딩중...", vXpos, vYpos, 130, 35, "sunken", 0, 0, true);
    }
};



/************************************************************* 
* 함수명   : ShowNoData()
* 설명       : 조회결과가 없음 표시를 Display 한다.
			sval : grid ID
*************************************************************/
/**
 * @method
 * @name ShowNoData
 * @description desc
 * @param {string} sval desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.ShowNoData = async function(sval) {
    var tem1 = sval.style.getStyle("width");
    var temLeft = sval.style.left;
    var temTop = sval.style.top;
    var tem2 = sval.style.getStyle("height");
    tem1 = tem1.substring(0, (tem1.length - 2));
    temLeft = temLeft.substring(0, (temLeft.length - 2));
    tem2 = tem2.substring(0, (tem2.length - 2));
    temTop = temTop.substring(0, (temTop.length - 2));
    vXpos = (eval(tem1 / 2) - 100) + Number(temLeft);
    vYpos = (eval(tem2 / 2) - 18) + Number(temTop);
    if ($c.frame.path("NoData") == null) {
        await $c.frame.CreateFrame("NoData", "/common/noData.gfm", "페이지 로딩중...", vXpos, vYpos, 200, 35, "sunken", 0, 0, true);
    }
};



/************************************************************* 
* 함수명   : CloseWin()
* 설명       : Display 중인 화면 로딩중 표시를 닫는다.
			cnt : 카운터 0 이면 ShowNoData()호출
			sval : grid id
*************************************************************/
/**
 * @method
 * @name CloseWin
 * @description desc
 * @param {string} cnt desc
 * @param {string} sval desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.CloseWin = async function(cnt, sval) {
    if ($c.frame.path("LoadingImg") != null) {
        await $c.frame.CloseFrame();
        if (cnt == 0) scwin.ShowNoData(sval);
    }
};




