/**
 * @method
 * @name fn_com_isur_sync
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_com_isur_sync = function() {
    var url;

    //2009.12.07(횝사팝업창에서 'js_bond_yn' 가 선언되어 있지 않을시 스크립트 오류발생. 인클루드 되어있지않을시 'N'으로 셋팅 P.H.J)
    try {
        js_bond_yn = js_bond_yn;
    } catch (E) {
        js_bond_yn = "N";
    }

    //2009.09.01 채권공시관련 추가
    if (js_bond_yn == 'Y') {
        url = "/isurcd.do?method=searchIsurCdBond&inputMessageId=isurcd&outputMessageId=isurcd&LIST_STAT_CD=&SPOT_ISU_TRD_MKT_TP_CD=";
    } else {
        url = "/isurcd.do?method=searchIsurCd&inputMessageId=isurcd&outputMessageId=isurcd&LIST_STAT_CD=Y&SPOT_ISU_TRD_MKT_TP_CD=" + scwin.js_com_market;
    }
    MxDataSet_com_isur.DataID = encodeURI(url);
    MxDataSet_com_isur.reset();
};
