skw;
foColum;
/**
 * @method
 * @name fn_com_isur_nm
 * @description desc
 * @param {string} keyCode desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_com_isur_nm = function(keyCode) {
    var cnt = 0;
    var len = js_com_Isurcd.getValue().length;
    var txtVal = js_com_Isurcd.getValue().toUpperCase();
    Grd_com_isur.setBroadcast("false");
    if (len > 0) {
        scwin.foColum = (isNaN(txtVal) ? 1 : 2);
    }
    if (scwin.foColum == 1) {
        scwin.skw = txtVal;
        if (window.event.keyCode == 13) {
            scwin.jongmokNameSearch();
        }
        /*
        				MxDataSet_com_isur.SortExpr="+COM_ABBRV";
        				MxDataSet_com_isur.Sort();
        				for(i=1; i<=MxDataSet_com_isur.countrow; i++){
        					var name = MxDataSet_com_isur.NameValue(i,"COM_ABBRV").substring(0,len).toUpperCase();
        					if (txtVal <= name){
        						cnt=i;
        						break;
        					}
        				}
        */
    } else {
        if (window.event.keyCode == 13) {
            scwin.fn_com_Confirm_set();
        } else {
            Grd_com_isur.style.display = "";
            scwin.skw = "";
            MxDataSet_com_isur.Filter();
            MxDataSet_com_isur.sort("+ISUR_CD", 0);
            MxDataSet_com_isur.Sort();
            for (i = 1; i <= MxDataSet_com_isur.getTotalRow(); i++) {
                var name = MxDataSet_com_isur.getCellData(i, "ISUR_CD").substring(0, len).toUpperCase();
                if (txtVal <= name) {
                    cnt = i;
                    break;
                }
            }
        }
    }
    Grd_com_isur.setBroadcast("true");
    MxDataSet_com_isur.setFocusedCell(cnt + 11, 0);
    MxDataSet_com_isur.setFocusedCell(cnt, 0);
};
/**
 * @method
 * @name isNumber
 * @description desc
 * @param {string} sVal desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.isNumber = function(sVal) {
    // 숫자인지 확인
    if (('0' < sVal) || ('9' > sVal)) {
        return true;
    } else {
        return false;
    }
};



//Ajax 사용하기 위한 함수(2009.11.20 P.H.J)
/**
 * @method
 * @name xmlDocLoad
 * @description desc
 * @param {string} strXml desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.xmlDocLoad = function(strXml) {
    xmlDoc = new ActiveXObject("Microsoft.XMLDOM");
    xmlDoc.async = false;
    if (!xmlDoc.loadXML(strXml)) {
        alert("error:" + xmlDoc.parseError.reason);
        //gSetXMLDataSync = false;
        xmlDoc = "";
        return "";
    }
    return xmlDoc;
};

