/************************************************************* 
 * 함수명   : ins_popupOpen(grdObj, grdObj2)
 * 설명       : 
 * 팝업호출 공통 
 * grdObj : 대상 값 받아올 CD
 * grdObj2 : 대상 값 받아올  VALUE
 * strUrl : 대상팝업 경로 (풀)
 * strTitle : 대상팝업 제목 (풀)
 * strW : 대상 팝업 가로길이  
 * strH : 대상 팝업 세로길이  
 * ins_popupOpen(txb_cd, txb_nm,대상팝업 경로 (풀),대상팝업 제목 (풀),대상 팝업 가로길이  ,대상 팝업 세로길이  );
 * ins_popupOpen("", txb_nm,대상팝업 경로 (풀),대상팝업 제목 (풀),대상 팝업 가로길이  ,대상 팝업 세로길이  );
 * ins_popupOpen(txb_cd, "",대상팝업 경로 (풀),대상팝업 제목 (풀),대상 팝업 가로길이  ,대상 팝업 세로길이  );
 *************************************************************/

obj_left;
obj_top;
/**
 * @method
 * @name ins_popup_TagetPos
 * @description desc
 * @param {string} grdObj desc
 * @param {string} grdObj2 desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.ins_popup_TagetPos = function(grdObj, grdObj2) {
    var cL = 7;
    var cT = 53;
    if (grdObj == "" || grdObj2 == "") {
        scwin.obj_left = "30";
        scwin.obj_top = "50";
    } else {
        scwin.obj_left = grdObj.style.left;
        scwin.obj_left = obj_left.substring(0, obj_left.length - 2);
        scwin.obj_left = eval(scwin.obj_left) + cL;
        scwin.obj_top = grdObj.style.top;
        scwin.obj_top = obj_top.substring(0, obj_top.length - 2);
        scwin.obj_top = eval(scwin.obj_top) + cT;
    }
};
/**
 * @method
 * @name ins_popupOpen
 * @description desc
 * @param {string} grdObj desc
 * @param {string} grdObj2 desc
 * @param {string} strUrl desc
 * @param {string} strTitle desc
 * @param {string} strW desc
 * @param {string} strH desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.ins_popupOpen = async function(grdObj, grdObj2, strUrl, strTitle, strW, strH) {
    js_ins_popup_cd = grdObj; //cd
    js_ins_popup_nm = grdObj2; //nm
    if (grdObj == "" || grdObj2 == "") {
        scwin.obj_left = "40";
        scwin.obj_top = "20";
    } else {
        scwin.ins_popup_TagetPos(grdObj, grdObj2);
    }
    strW = eval(strW) + 10;
    strH = eval(strH) + 10;
    await $c.frame.CreateDialogFrame("ins_popup", "/common/" + strUrl + ".gfm", strTitle, scwin.obj_left, scwin.obj_top, strW, strH, "tool");
};


