/************************************************************* 
 * 함수명   : ins_combo_set(dtsObj, vScrenID, SCREN_PROCS_TP_CD ,cdId , flag)
 * 설명       :   
 * dtsObj : 콤보 Object
 * vScrenID: 화면ID 
 * SCREN_PROCS_TP_CD : 조회 01
 * cdId : 공통 코드 ID (조회대상)
 * flag : 디폴트 구분 
 *************************************************************/
/**
 * @method
 * @name ins_combo_set
 * @description desc
 * @param {string} dtsObj desc
 * @param {string} vScrenID desc
 * @param {string} SCREN_PROCS_TP_CD desc
 * @param {string} cdId desc
 * @param {string} flag desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.ins_combo_set = function(dtsObj, vScrenID, SCREN_PROCS_TP_CD, cdId, flag) {
    var method = "";
    if (flag == "ALL") {
        method = "listCodeValueNameAll"; // defaul 전체

    } else if (flag == "SEL") {
        method = "listCodeValueNameSelect"; // defaul 빈칸 

    } else if (flag == "CPBO") {
        method = "listCodeValueNameCPBO"; // CPBO 신용등급

    } else {
        method = "listCodeValueNameM"; // defaul 없음  

    }
    var url = "/CodeAction.do?method=" + method;
    url += "&SCREN_ID=" + vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD;
    url += "&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT";
    url += "&CD_ID_M='" + cdId + "'";
    url += "&CD_ID_FLAG=A";

    //alert(url);

    dtsObj.DataID = url;
    dtsObj.Reset();
};



/************************************************************* 
 * 함수명   : ins_combo_set2(dtsObj, vScrenID, SCREN_PROCS_TP_CD ,cdId , flag, del_cd)
