 * @exception
 * @example
 */
scwin.ins_combo_set2 = function(dtsObj, vScrenID, SCREN_PROCS_TP_CD, cdId, flag, del_cd) {
    var method = "";
    if (flag == "ALL") {
        method = "listCodeValueNameAll"; // defaul 전체

    } else if (flag == "SEL") {
        method = "listCodeValueNameSelect"; // defaul 빈칸 

    } else if (flag == "CPBO") {
        method = "listCodeValueNameCPBO"; // CPBO 신용등급

    } else {
        method = "listCodeValueNameM"; // defaul 없음  

    }
    var url = "/CodeAction.do?method=" + method;
    url += "&SCREN_ID=" + vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD;
    url += "&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT";
    url += "&CD_ID_M=" + cdId;
