/******************************************************************* 
 * 함수명   : fn_ResetCdValue
 * 설명     : 콤보데이터를 'CODE VALUE' 형태로 재가공한다.
 * argument : cbDs
 *******************************************************************/
/**
 * @method
 * @name fn_ResetCdValue
 * @description desc
 * @param {string} cbDs desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_ResetCdValue = function(cbDs) {
    for (var i = 1; i <= cbDs.getTotalRow(); i++) {
        cbDs.setCellData(i, "TEXT", cbDs.getCellData(i, "VALUE") + ' ' + cbDs.getCellData(i, "TEXT"));
    }
};



