        strW = "770";
        strH = "670";
        strTitle = "ETN";
    } else if (STD_CD_STATE == "KR1" || STD_CD_STATE == "KR2" || STD_CD_STATE == "KR3" ||
        STD_CD_STATE == "KRB") {
        // 국채,지방채, 특수채, 회사채, 외국채권
        strUrl = "ULDINS91900"; // 채권 
