        strH = "790";
        strTitle = "채권";
    } else if (STD_CD_STATE == "KR4") {
        // 선물옵션
        strUrl = "ULDINS93000"; // 선물옵션 
        strW = "770";
        strH = "590";
        strTitle = "선물옵션";
    } else if (STD_CD_STATE == "KR5") {
        // 수익증권/개발신탁
        strUrl = "ULDINS92200"; // 수익증권/개발신탁 
        strW = "770";
        strH = "590";
        strTitle = "수익증권";
    } else if (STD_CD_STATE == "KR7") {
        // 주권 
        strUrl = "ULDINS92100";
        strW = "770";
        strH = "590";
        strTitle = "주권";
    } else if (STD_CD_STATE == "KR8") {
        // 유가증권예탁증서
        strUrl = "ULDINS92500";
        strW = "770";
        strH = "600";
        strTitle = "유가증권예탁증서";
    } else if (STD_CD_STATE == "KRA") {
        // 신주인수권

        if (KND == "주식워런트" || KND.indexOf("주식워런트") > -1) {
            strUrl = "ULDINS92400";
            strW = "770";
            strH = "830";
            strTitle = "주식워런트";
        } else {
            strUrl = "ULDINS92300"; // 신주인수권
            strW = "770";
            strH = "590";
            strTitle = "신주인수권증권/증서";
        }
    } else if (STD_CD_STATE == "KRE") {
        // CD
        strUrl = "ULDINS92600";
        strW = "770";
        strH = "630";
        strTitle = "CD";
    } else if (STD_CD_STATE == "KRF") {
        // CP, 전자단기채권
        if (KND == "전자단기사채") {
            strUrl = "ULDINS92800";
            strW = "770";
            strH = "740";
            strTitle = "전자단기사채";
        } else {
            strUrl = "ULDINS92700"; // CP
            strW = "770";
            strH = "700";
            strTitle = "CP";
        }
    } else if (STD_CD_STATE == "KRD") {
        // 지표
        strUrl = "ULDINS92900";
        strW = "770";
        strH = "590";
        strTitle = "지표";
    } else if (STD_CD_STATE == "KRG") {
        // ETN
        strUrl = "ULDINS94100"; // ETN
        strW = "770";
        strH = "670";
        strTitle = "ETN";
    } else if (STD_CD_STATE == "KRH") {
        // 투자계약증권
        strUrl = "ULDINS94200";
        strW = "750";
        strH = "635";
        strTitle = "투자계약증권";
    } else {
        if (KND == "주권") {
            strUrl = "ULDINS92100";
            strW = "770";
            strH = "590";
            strTitle = "주권";
        } else if (KND == "ELS_DLS" || KND == "ELS/DLS" || KND == "ELS/DLS/ELB/DLB") {
            strUrl = "ULDINS93500"; // ELS_DLS
            strW = "770";
            strH = "670";
            strTitle = "ELS/ELB,DLS/DLB";
