            strUrl = "ULDINS92300"; // 신주인수권 증권/증서
            strW = "770";
            strH = "590";
            strTitle = "신주인수권증권/증서";
        } else {

        }
    }
    if (strUrl == "") {
        alert("유가증권종류 확인 불가 \n 상세정보를 조회할 수 없습니다.");
        return;
    }
    strTitle = "* 처리 [" + strTitle + " 상세_" + strUrl + "]";
    strW = eval(strW) + 10;
    strH = eval(strH) + 10;
    await $c.frame.CreateDialogFrame("ins_popup", "/common/" + strUrl + ".gfm", strTitle, 40, 20, strW, strH, "tool");
};




