/************************************************************* 
 * 함수명   : fn_CtrlBtn
 * 설명       : 
 * 팝업호출 공통 
 * 버튼 활성 비활성화 정의 한다. 
 * insert  등록 
 * update 수정 
 *************************************************************/
/**
 * @method
 * @name fn_CtrlBtn
 * @description desc
 * @param {string} pFg desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CtrlBtn = function(pFg) {
    if (pFg == "insert") {
        if (document.getElementById("btn_new")) {
            btn_new.setDisabled(true);
            btn_new.src = "../img/btn_new_d.gif";
        }
        if (document.getElementById("btn_save")) {
            btn_save.setDisabled(false);
            btn_save.src = "../img/btn_save.gif";
        }
        if (document.getElementById("btn_modify")) {
            btn_modify.setDisabled(true);
            btn_modify.src = "../img/btn_modify_d.gif";
        }
        if (document.getElementById("btn_delete")) {
            btn_modify.setDisabled(true);
            btn_delete.src = "../img/btn_delete_d.gif";
        }
        if (document.getElementById("btn_prcnm")) {
            btn_prcnm.setDisabled(true); // 처리자조회
            btn_prcnm.src = "../img/btn_prcnm_d.gif";
        }
    } else if (pFg == "update") {
        if (document.getElementById("btn_new")) {
            btn_new.setDisabled(false);
            btn_new.src = "../img/btn_new.gif";
        }
        if (document.getElementById("btn_save")) {
            btn_save.setDisabled(true);
            btn_save.src = "../img/btn_save_d.gif";
        }
        if (document.getElementById("btn_modify")) {
            btn_modify.setDisabled(false);
            btn_modify.src = "../img/btn_modify.gif";
        }
        if (document.getElementById("btn_delete")) {
            btn_delete.setDisabled(false);
            btn_delete.src = "../img/btn_delete.gif";
        }
        if (document.getElementById("btn_createstdcd")) {
            btn_createstdcd.setDisabled(false); // 표준코드등록
            btn_createstdcd.src = "../img/btn_createstdcd.gif";
        }
        if (document.getElementById("btn_ret")) {
            btn_ret.setDisabled(false); // 반송
            btn_ret.src = "../img/btn_Ret.gif";
        }
        if (document.getElementById("btn_file")) {
            btn_file.setDisabled(false); // 첨부파일
            btn_file.src = "../img/btn_file.gif";
        }
        if (document.getElementById("btn_prcnm")) {
            btn_prcnm.setDisabled(false); // 처리자조회
            btn_prcnm.src = "../img/btn_prcnm.gif";
        }
        if (document.getElementById("btn_clearPwd")) {
            btn_clearPwd.setDisabled(false); //  비밀번호 초기화 
            btn_clearPwd.src = "../img/btn_clearPwd.gif";
        }
        if (document.getElementById("btn_allIssue")) {
            btn_allIssue.setDisabled(false); //  일괄 발급 
            btn_allIssue.src = "../img/btn_allIssue.gif";
        }
    } else {
        if (document.getElementById("btn_new")) {
            btn_new.setDisabled(false);
            btn_new.src = "../img/btn_new.gif";
        }
        if (document.getElementById("btn_save")) {
            btn_save.setDisabled(true);
