 */
scwin.fn_apct_delchar = function(addObj) {
    if (addObj == undefined) {
        return;
    }
    for (var i = 0; i < addObj.length; i++) {
        textBox = addObj[i];
        addObj[i].attachEvent("onkeyup", function() {
            scwin.fn_DelChar(textBox);
        });
    }
};




