/**
 * @method
 * @name fn_apct_delchar
 * @description desc
 * @param {string} objttt desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_apct_delchar = function(objttt) {
    if (objttt.addEventListener) {
        objttt.addEventListener("keyup", function() {
            scwin.fn_DelChar(objttt);
        }, false);
    } else {
        objttt.attachEvent("onkeyup", function() {
            scwin.fn_DelChar(objttt);
        });
    }
};






// 틀린항목 배경색 바꿔준다.
/**
 * @method
 * @name fn_ChangeCheck
 * @description desc
 * @param {string} arrayObj1 desc
 * @param {string} arrayObj2 desc
 * @param {string} Gubun desc
 * @param {string} Bf_Color desc
 * @param {string} Color desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_ChangeCheck = function(arrayObj1, arrayObj2, Gubun, Bf_Color, Color) {
    var Obj1;
    var Obj2;
    var Obj1_value;
    var Obj2_value;
    var flag = "N";
    if (Bf_Color == undefined) Bf_Color = "#B9D4F7";
    if (Color == undefined) Color = "#EEF6FE";
    for (var i = 0; i < arrayObj1.length; i++) {
        isChange = "N";
        Obj1 = arrayObj1[i];
        Obj2 = arrayObj2[i];
        Obj1_value = $c.stf.getObjectValue(Obj1);
        Obj2_value = $c.stf.getObjectValue(Obj2);
        if (Obj2.id.substring(0, 3) == "txb") {
            Obj1.style.backgroundColor = Bf_Color;
            Obj2.style.backgroundColor = Bf_Color;
        }
        if (Obj2.id.substring(0, 3) == "edt") {
            Obj1.readonlybackcolor = Bf_Color;
            Obj2.readonlybackcolor = Bf_Color;
        }
        if (Obj2.id.substring(0, 3) == "cmb") {
            Obj1.disablebackcolor = Bf_Color;
            Obj2.disablebackcolor = Bf_Color;
            Obj2_value = Obj2.getText();
            if (Obj2_value.indexOf(" ") > -1) {
                Obj2_value = Obj2_value.substring(Obj2_value.indexOf(" ") + 1);
            }
        }
        if (Obj1_value != Obj2_value) isChange = "Y";
        if (isChange == "Y") {
            if (Gubun == "right") {
                if (Obj2.id.substring(0, 3) == "txb") {
                    Obj2.style.backgroundColor = Color;
                }
                if (Obj2.id.substring(0, 3) == "edt") {
                    Obj2.ReadOnlyBackColor = Color;
                }
                if (Obj2.id.substring(0, 3) == "cmb") {
                    Obj2.disablebackcolor = Color;
                    Obj2.setDisabled(false);
                }
            } else if (Gubun == "left") {
                if (Obj2.id.substring(0, 3) == "txb") {
                    Obj1.style.backgroundColor = Color;
                }
                if (Obj2.id.substring(0, 3) == "edt") {
                    Obj1.readonlybackcolor = Color;
                }
                if (Obj2.id.substring(0, 3) == "cmb") {
                    Obj1.disablebackcolor = Color;
                }
            } else if (Gubun == "both") {
                if (Obj1.id.substring(0, 3) == "txb") {
                    Obj1.style.backgroundColor = Color;
                }
                if (Obj1.id.substring(0, 3) == "edt") {
                    Obj1.readonlybackcolor = Color;
                }
                if (Obj1.id.substring(0, 3) == "cmb") {
                    Obj1.disablebackcolor = Color;
                }
                if (Obj2.id.substring(0, 3) == "txb") {
                    Obj2.style.backgroundColor = Color;
                }
                if (Obj2.id.substring(0, 3) == "edt") {
                    Obj2.readonlybackcolor = Color;
                }
                if (Obj2.id.substring(0, 3) == "cmb") {
                    Obj2.disablebackcolor = Color;
                }
            }
        }
    }
};



// 오늘날짜 이전은 불가하다.
/**
 * @method
 * @name fn_checkDay
 * @description desc
 * @param {string} obj desc
 * @param {string} label desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_checkDay = function(obj, label) {
    var clientnow = new Date();

    /* 오늘 날짜를 구한다 */
    var curYear = clientnow.getYear();
    var curMonth = (clientnow.getMonth()) + 1;
    var curDay = clientnow.getDate();
    var day = $c.stf.getObjectValue(obj);
    if (day < curYear.toString() + curMonth.toString() + curDay.toString()) {
        alert("[" + label + "] 을(를) 오늘 이전날짜로 등록하지 마십시요.");
        obj.focus();
        return false;
    }
};





